<?php
define('PAGE_TITLE','Review Submission Artifact');
require_once __DIR__.'/../../config/config.php';require_once __DIR__.'/../../config/db.php';
require_once __DIR__.'/../../includes/auth.php';require_once __DIR__.'/../../includes/system.php';require_once __DIR__.'/../../includes/workflow.php';
requireAuth();$role=qps_workflow_role();if($role==='DEAN')requireDean();elseif($role==='COE')qps_workflow_require_role(['COE']);elseif($role==='STAFF' && (strtoupper((string)(getCurrentUser()['role']??''))==='HOD' || !empty(getCurrentUser()['is_hod'])) && empty(getCurrentUser()['is_erp_staff'])){$_SESSION['qps_portal_role']='HOD';$role='HOD';}elseif($role!=='HOD'){http_response_code(403);exit('Review access denied.');}
$pdo=getDBConnection();if(empty($_SESSION['qps_review_csrf']))$_SESSION['qps_review_csrf']=bin2hex(random_bytes(32));$csrf=$_SESSION['qps_review_csrf'];
$id=(int)($_GET['package_id']??0);$artifact=(string)($_GET['artifact']??'questions');
$st=$pdo->prepare("SELECT p.*,d.course_title,d.dept_name,d.total_questions FROM qps_submission_packages p LEFT JOIN qps_question_bank_drafts d ON d.id=p.bank_draft_id WHERE p.id=? LIMIT 1");$st->execute([$id]);$pkg=$st->fetch(PDO::FETCH_ASSOC);
if (!$pkg || strtoupper((string)$pkg['status']) === 'DRAFT') { http_response_code(404); exit('Submission package not found.'); }
if ($role === 'HOD') {
  $currentUser = getCurrentUser();
  $dept = strtoupper(trim((string)($currentUser['dept_code'] ?? '')));
  if ($dept === '' || strtoupper(trim((string)($pkg['dept_code'] ?? ''))) !== $dept) { http_response_code(403); exit('This course belongs to another department.'); }
}
$activeStates = ['HOD'=>['SUBMITTED_TO_HOD','HOD_RECHECK','DEAN_REMARKS'],'DEAN'=>['SUBMITTED_TO_DEAN'],'COE'=>['SUBMITTED_TO_COE']];
$canAct = strtoupper((string)($pkg['current_owner_role'] ?? '')) === $role && in_array($pkg['status'], $activeStates[$role] ?? [], true);
$canAddRemark = $canAct && (($role === 'HOD' && in_array($pkg['status'], ['SUBMITTED_TO_HOD','HOD_RECHECK'], true)) || ($role === 'DEAN' && $pkg['status'] === 'SUBMITTED_TO_DEAN'));
$canDeleteQuestion = $canAct && $role === 'HOD' && in_array($pkg['status'], ['SUBMITTED_TO_HOD','HOD_RECHECK'], true);
$questions=[];$slots=[];$qbb=null;$draftId=(int)($pkg['bank_draft_id']??0);
if($artifact==='questions'&&$draftId){$st=$pdo->prepare('SELECT * FROM qps_question_bank_draft_questions WHERE draft_id=? ORDER BY q_number,id');$st->execute([$draftId]);$questions=$st->fetchAll(PDO::FETCH_ASSOC);}
elseif($artifact==='qbb'&&$pkg['qbb_id']){$st=$pdo->prepare('SELECT * FROM question_bank_blueprints WHERE id=?');$st->execute([$pkg['qbb_id']]);$qbb=$st->fetch(PDO::FETCH_ASSOC);}
elseif($artifact==='final'&&$pkg['final_blueprint_id']){$st=$pdo->prepare('SELECT * FROM qps_final_blueprints WHERE id=?');$st->execute([$pkg['final_blueprint_id']]);$fb=$st->fetch(PDO::FETCH_ASSOC);$slots=json_decode((string)($fb['slots_config']??''),true)?:[];if(isset($slots['slots']))$slots=$slots['slots'];}
else{http_response_code(404);exit('Requested artifact was not found.');}
require_once __DIR__.'/../../includes/header.php';require_once __DIR__.'/../../includes/navbar.php';require_once __DIR__.'/../../includes/sidebar.php';
?>
<main class="max-w-7xl mx-auto px-4 sm:px-6 py-6 space-y-5">
 <a href="submitted.php" class="text-sm font-bold text-indigo-700 hover:text-indigo-900">← Back to Submitted Courses</a><?php if(!$canAct):?><div class="rounded-xl border border-slate-200 bg-slate-50 p-3 text-sm text-slate-600">Read-only view — this package is currently owned by <?=htmlspecialchars((string)($pkg['current_owner_role']??'another role'))?> or is no longer awaiting your action.</div><?php endif;?>
 <div class="bg-white border rounded-2xl p-5"><p class="text-xs font-black uppercase text-indigo-600"><?=$role?> Review</p><h1 class="text-2xl font-black"><?=htmlspecialchars($pkg['paper_code'])?></h1><p class="text-sm text-slate-500"><?=htmlspecialchars($pkg['course_title']??'')?> · <?=htmlspecialchars($pkg['semester'].' · '.$pkg['academic_year'])?></p><div class="flex flex-wrap gap-2 mt-4"><?php foreach(['questions'=>'Question Bank','qbb'=>'Question Bank Blueprint','final'=>'Final Blueprint'] as $a=>$label):?><a class="px-3 py-2 rounded-xl text-xs font-bold <?=$artifact===$a?'bg-indigo-600 text-white':'bg-slate-100'?>" href="?package_id=<?=$id?>&artifact=<?=$a?>"><?=$label?></a><?php endforeach;?></div></div>
 <?php if($artifact==='questions'):?>
  <?php foreach($questions as $q):?><article class="bg-white border rounded-2xl p-5 space-y-3 <?=($q['correction_status']??'')==='NEEDS_CORRECTION'?'border-rose-300 bg-rose-50':''?>">
   <div class="flex justify-between gap-2"><strong>Q<?=htmlspecialchars((string)$q['q_number'])?> · Unit <?=htmlspecialchars((string)$q['unit_no'].'.'.$q['sub_unit'])?></strong><span class="text-xs font-bold"><?=htmlspecialchars($q['question_type'].' · '.$q['marks'].' marks · '.$q['k_level'].' / '.$q['co_level'])?></span></div>
   <div class="text-sm whitespace-pre-wrap"><?=htmlspecialchars($q['question_text'])?></div>
   <?php if(!empty($q['remarks'])):?><p class="text-sm text-rose-700 font-semibold">Remark: <?=htmlspecialchars($q['remarks'])?></p><?php endif;?>
   <div class="flex gap-2"><?php if($canAddRemark):?><button class="remarkBtn px-3 py-2 rounded-lg bg-rose-100 text-rose-800 text-xs font-black" data-type="QUESTION" data-ref="<?=$q['id']?>">Remark</button><?php endif;?><?php if($canDeleteQuestion):?><button class="deleteBtn px-3 py-2 rounded-lg bg-slate-100 text-slate-700 text-xs font-black" data-id="<?=$q['id']?>">Delete</button><?php endif;?></div>
  </article><?php endforeach;?>
 <?php elseif($artifact==='qbb'):?>
  <div class="bg-white border rounded-2xl p-5"><h2 class="font-black mb-3">Question Bank Blueprint</h2><p class="text-sm text-slate-600 mb-3"><?=htmlspecialchars($qbb['course_title']??'')?></p><pre class="text-xs whitespace-pre-wrap overflow-auto bg-slate-50 p-4 rounded-xl"><?=htmlspecialchars(json_encode(json_decode((string)($qbb['matrix_json']??''),true)?:[],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE))?></pre><?php if($canAddRemark):?><button class="remarkBtn mt-3 px-3 py-2 rounded-lg bg-rose-100 text-rose-800 text-xs font-black" data-type="QBB" data-ref="QBB">Remark on blueprint</button><?php endif;?></div>
 <?php else:?>
  <div class="bg-white border rounded-2xl p-5 overflow-x-auto"><h2 class="font-black mb-3">Final Question Slot Allocation (Master Blueprint Specification)</h2><table class="w-full text-sm"><thead class="bg-slate-50"><tr><th class="p-3 text-left">Question</th><th class="p-3">Unit</th><th class="p-3">Subunit</th><th class="p-3">Type</th><th class="p-3">Marks</th><th class="p-3">K-Level</th><th class="p-3">CO-Level</th><th class="p-3">Action</th></tr></thead><tbody><?php foreach($slots as $i=>$slot):?><tr class="border-t"><td class="p-3"><?=htmlspecialchars((string)($slot['slot_key']??'Q'.($i+1)))?></td><td class="p-3 text-center"><?=htmlspecialchars((string)($slot['unit_no']??''))?></td><td class="p-3 text-center"><?=htmlspecialchars((string)($slot['sub_unit']??''))?></td><td class="p-3 text-center"><?=htmlspecialchars((string)($slot['question_type']??''))?></td><td class="p-3 text-center"><?=htmlspecialchars((string)($slot['marks']??''))?></td><td class="p-3 text-center"><?=htmlspecialchars((string)($slot['k_level']??''))?></td><td class="p-3 text-center"><?=htmlspecialchars((string)($slot['co_level']??''))?></td><td class="p-3"><?php if($canAddRemark):?><button class="remarkBtn px-3 py-1 rounded-lg bg-rose-100 text-rose-800 text-xs font-black" data-type="FINAL_SLOT" data-ref="<?=htmlspecialchars((string)($slot['slot_key']??'Q'.($i+1)))?>">Remark</button><?php else:?>—<?php endif;?></td></tr><?php endforeach;?></tbody></table></div>
 <?php endif;?>
 <?php if($canAct): ?><div class="bg-white border rounded-2xl p-5 flex flex-wrap gap-2">
 <?php if($role==='HOD'):?><button id="sendBack" class="px-4 py-3 rounded-xl bg-rose-600 text-white font-black text-sm"><?= $pkg['status']==='DEAN_REMARKS'?'Forward Dean Remarks to Staff':'Send Remarks to Staff' ?></button><?php if($pkg['status']!=='DEAN_REMARKS'):?><button id="forward" class="px-4 py-3 rounded-xl bg-indigo-600 text-white font-black text-sm"><?= $pkg['status']==='HOD_RECHECK'?'Verify & Resend to Dean':'Verify & Send to Dean' ?></button><?php endif;?><?php elseif($role==='DEAN'):?><button id="sendBack" class="px-4 py-3 rounded-xl bg-rose-600 text-white font-black text-sm">Send Remarks to HOD</button><button id="forward" class="px-4 py-3 rounded-xl bg-indigo-600 text-white font-black text-sm">Approve & Send to COE</button><?php else:?><button id="forward" class="px-4 py-3 rounded-xl bg-emerald-600 text-white font-black text-sm">COE Approve & Unlock Final Allotment</button><?php endif;?>
 </div><?php endif; ?>
</main>
<script>
const canAct = <?= $canAct ? 'true' : 'false' ?>;
const csrf=<?=json_encode($csrf)?>,packageId=<?=$id?>,role=<?=json_encode($role)?>,status=<?=json_encode($pkg['status'])?>;let remarkCount=0;
async function post(url,data){if(!canAct)throw new Error('This package is read-only for your role.');const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...data,csrf})});const d=await r.json();if(!d.success)throw new Error(d.message||'Request failed');return d;}
document.querySelectorAll('.remarkBtn').forEach(b=>b.addEventListener('click',async()=>{const msg=prompt('Enter the correction / review remark:');if(!msg||!msg.trim())return;try{await post('<?=htmlspecialchars(getBaseUrl())?>/api/remarks.php',{action:'add',package_id:packageId,target_type:b.dataset.type,target_ref:b.dataset.ref,remark_text:msg.trim()});remarkCount++;b.textContent='Remark added';b.disabled=true;alert('Remark saved. Use the return button to send the course back.');}catch(e){alert(e.message);}}));
document.querySelectorAll('.deleteBtn').forEach(b=>b.addEventListener('click',async()=>{if(!confirm('Delete this draft question?'))return;try{await post('<?=htmlspecialchars(getBaseUrl())?>/api/remarks.php',{action:'delete_question',package_id:packageId,question_id:Number(b.dataset.id)});location.reload();}catch(e){alert(e.message);}}));
const sendBackButton=document.getElementById('sendBack');if(sendBackButton)sendBackButton.onclick=async()=>{if(!remarkCount&&!confirm('No new remarks were added on this page. Send the package back anyway?'))return;try{await post('<?=htmlspecialchars(getBaseUrl())?>/api/workflow.php',{action:role==='HOD'?(status==='DEAN_REMARKS'?'hod_forward_dean_remarks':'hod_return'):'dean_return',package_id:packageId,note:'Review remarks sent.'});location.href='index.php';}catch(e){alert(e.message);}};
const forwardButton=document.getElementById('forward');if(forwardButton)forwardButton.onclick=async()=>{if(remarkCount){alert('You have added remarks. Send the course back instead of forwarding.');return;}try{await post('<?=htmlspecialchars(getBaseUrl())?>/api/workflow.php',{action:role==='HOD'?(status==='HOD_RECHECK'?'hod_reverify':'hod_forward'):(role==='DEAN'?'dean_approve':'coe_approve'),package_id:packageId,note:'All three artifacts reviewed.'});if(role==='COE'){const r=await fetch('<?=htmlspecialchars(getBaseUrl())?>/api/verify_bank.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'coe_approve_and_commit',draft_id:<?=$draftId?>,csrf})});const d=await r.json();if(!d.success)throw new Error(d.message||'Question bank commit failed.');}location.href='index.php';}catch(e){alert(e.message);}};
</script>
<?php require_once __DIR__.'/../../includes/footer.php';?>
